const GUARD_VERSION = "g1";
const MAX_BODY_CHARS = 6000;

const counters = {};
const seen = {};
const typesFound = [];

function token(type, value) {
  const key = type + "|" + String(value).toLowerCase().replace(/[\s().-]/g, "");
  if (!seen[key]) {
    counters[type] = (counters[type] || 0) + 1;
    seen[key] = "[" + type + "_" + counters[type] + "]";
    if (!typesFound.includes(type)) typesFound.push(type);
  }
  return seen[key];
}

function luhnOk(digits) {
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = Number(digits[i]);
    if (double) { d *= 2; if (d > 9) d -= 9; }
    sum += d;
    double = !double;
  }
  return sum % 10 === 0;
}

function looksLikeSecret(value) {
  if (/^\d{4,8}$/.test(value)) return true;
  return value.length >= 6 && /[A-Za-z]/.test(value) && /[\d!@#$%^&*]/.test(value);
}

function maskText(text) {
  let t = String(text || "").replace(/\p{Cf}/gu, "");

  t = t.replace(/\b(password|passwd|pwd|passcode|passphrase|pin|otp|api[ _-]?key|secret|token)\b(\s*(?:is|was|:|=)?\s*)(\S+)/gi, (m, word, sep, value) => {
    const clean = value.replace(/[.,;)\]]+$/, "");
    if (!looksLikeSecret(clean)) return m;
    return word + sep + token("SECRET", clean) + value.slice(clean.length);
  });
  t = t.replace(/\b(?:sk-[A-Za-z0-9_-]{16,}|xox[abprs]-[A-Za-z0-9-]{10,}|AKIA[0-9A-Z]{16}|gh[pousr]_[A-Za-z0-9]{20,})/g, (m) => token("SECRET", m));

  t = t.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, (m) => token("EMAIL", m));

  t = t.replace(/\b(?:\d[ -]?){12,18}\d\b/g, (m) => (luhnOk(m.replace(/\D/g, "")) ? token("CARD", m) : m));
  t = t.replace(/\b\d{3}-\d{2}-\d{4}\b/g, (m) => token("SSN", m));
  t = t.replace(/\b[A-Z]{5}\d{4}[A-Z]\b/g, (m) => token("PAN", m));
  t = t.replace(/\b[2-9]\d{3}[ -]\d{4}[ -]\d{4}\b/g, (m) => token("AADHAAR", m));

  t = t.replace(/(?<![\w\]])(?:\+|00)\d{1,3}[ -]?(?:\d[ -]?){8,11}\d\b/g, (m) => token("PHONE", m));
  t = t.replace(/\b[6-9]\d{9}\b/g, (m) => token("PHONE", m));
  t = t.replace(/(?<![\w\]])\(?\d{3}\)?[ .-]\d{3}[ .-]\d{4}\b/g, (m) => token("PHONE", m));

  return t;
}

const INJECTION_RULES = [
  ["ignore instructions", /\b(ignore|disregard|forget|override|bypass)\b\s+(?:all |any |the |your |these |those |my )*(?:previous|prior|above|earlier|preceding|system|original|safety|your)\b[^.\n]{0,30}\b(instructions?|prompts?|rules?|guidelines?|directions?)/i],
  ["ignore instructions", /\b(ignore|disregard)\b\s+(?:all|any|your|the)\s+(instructions|rules|guidelines)\b/i],
  ["role change", /\b(you are now|from now on,? you|act as (?:a|an|the|if)\b|pretend (?:to be|you are)|new (?:role|persona|instructions?)\s*:)/i],
  ["prompt probing", /\b(system prompt|developer message|hidden instructions?)\b|\b(reveal|show|print|repeat)\b[^.\n]{0,30}\b(your|the) (prompt|instructions)\b/i],
  ["classification steering", /\b(classify|categori[sz]e|mark|label|set|treat|rate)\b[^.\n]{0,40}\b(as|to|=)\s*(p[1-4]\b|needs_human|approved|resolved|false|true)/i],
  ["approval bypass", /\b(auto[- ]?approve|skip (?:the )?(?:approval|review|human)|without (?:any )?(?:approval|review|a human)|do not (?:escalate|notify|alert))\b/i],
  ["chat markup", /<\/?(?:system|assistant|instructions?|prompt)>|\[\/?INST\]|^\s*(?:system|assistant)\s*:/im],
  ["jailbreak wording", /\b(jailbreak|DAN mode|developer mode)\b/i]
];

function checkInjection(text) {
  const flat = String(text || "").replace(/\p{Cf}/gu, "").replace(/[ \t]+/g, " ");
  const signals = [];
  for (const [label, pattern] of INJECTION_RULES) {
    if (pattern.test(flat) && !signals.includes(label)) signals.push(label);
  }
  return signals;
}

const rawBody = String($json.body || "");
const truncated = rawBody.length > MAX_BODY_CHARS;
const body = truncated ? rawBody.slice(0, MAX_BODY_CHARS) : rawBody;

const signals = checkInjection(String($json.subject || "") + "\n" + body);

const safeSubject = maskText($json.subject);
const safeBody = maskText(body) + (truncated ? "\n[TRUNCATED]" : "");

let piiCount = 0;
for (const type of Object.keys(counters)) piiCount += counters[type];
const bodyTypes = typesFound.slice();

const safeFrom = maskText($json.from);

return {
  json: {
    safe_from: safeFrom,
    safe_subject: safeSubject,
    safe_body: safeBody,
    pii_count: piiCount,
    pii_types: bodyTypes,
    injection_suspected: signals.length > 0,
    injection_signals: signals,
    truncated,
    guard_version: GUARD_VERSION
  }
};
